package runtime_test

import (
	"fmt"
	"os"
	"runtime"
	"strings"
)

func ExampleFrames() {
	c := func() {
		// Ask runtime.Callers for up to 10 PCs, including runtime.Callers itself.
		pc := make([]uintptr, 10)
		n := runtime.Callers(0, pc)
		if n == 0 {
			// No PCs available. This can happen if the first argument to
			// runtime.Callers is large.
			//
			// Return now to avoid processing the zero Frame that would
			// otherwise be returned by frames.Next below.
			return
		}

		pc = pc[:n] // pass only valid pcs to runtime.CallersFrames
		frames := runtime.CallersFrames(pc)

		// Loop to get frames.
		// A fixed number of PCs can expand to an indefinite number of Frames.
		for {
			frame, more := frames.Next()

			// Canonicalize function name and skip callers of this function
			// for predictable example output.
			// You probably don't need this in your own code.
			function := strings.ReplaceAll(frame.Function, "main.main", "runtime_test.ExampleFrames")
			fmt.Printf("- more:%v | %s\n", more, function)
			if function == "runtime_test.ExampleFrames" {
				break
			}

			// Check whether there are more frames to process after this one.
			if !more {
				break
			}
		}
	}

	b := func() { c() }
	a := func() { b() }

	a()
	// Output:
	// - more:true | runtime.Callers
	// - more:true | runtime_test.ExampleFrames.func1
	// - more:true | runtime_test.ExampleFrames.func2
	// - more:true | runtime_test.ExampleFrames.func3
	// - more:true | runtime_test.ExampleFrames
}

func ExampleAddCleanup() {
	tempFile, err := os.CreateTemp(os.TempDir(), "file.*")
	if err != nil {
		fmt.Println("failed to create temp file:", err)
		return
	}

	ch := make(chan struct{})

	// Attach a cleanup function to the file object.
	runtime.AddCleanup(&tempFile, func(fileName string) {
		if err := os.Remove(fileName); err == nil {
			fmt.Println("temp file has been removed")
		}
		ch <- struct{}{}
	}, tempFile.Name())

	if err := tempFile.Close(); err != nil {
		fmt.Println("failed to close temp file:", err)
		return
	}

	// Run the garbage collector to reclaim unreachable objects
	// and enqueue their cleanup functions.
	runtime.GC()

	// Wait until cleanup function is done.
	<-ch

	// Output:
	// temp file has been removed
}

package cgo // import "runtime/cgo"

Package cgo contains runtime support for code generated by the cgo tool.
See the documentation for the cgo command for details on using cgo.

TYPES

type Handle uintptr
    Handle provides a way to pass values that contain Go pointers (pointers to
    memory allocated by Go) between Go and C without breaking the cgo pointer
    passing rules. A Handle is an integer value that can represent any Go value.
    A Handle can be passed through C and back to Go, and Go code can use the
    Handle to retrieve the original Go value.

    The underlying type of Handle is guaranteed to fit in an integer type that
    is large enough to hold the bit pattern of any pointer. The zero value of a
    Handle is not valid, and thus is safe to use as a sentinel in C APIs.

    For instance, on the Go side:

        package main

        /*
        #include <stdint.h> // for uintptr_t

        extern void MyGoPrint(uintptr_t handle);
        void myprint(uintptr_t handle);
        */
        import "C"
        import "runtime/cgo"

        //export MyGoPrint
        func MyGoPrint(handle C.uintptr_t) {
        	h := cgo.Handle(handle)
        	val := h.Value().(string)
        	println(val)
        	h.Delete()
        }

        func main() {
        	val := "hello Go"
        	C.myprint(C.uintptr_t(cgo.NewHandle(val)))
        	// Output: hello Go
        }

    and on the C side:

        #include <stdint.h> // for uintptr_t

        // A Go function
        extern void MyGoPrint(uintptr_t handle);

        // A C function
        void myprint(uintptr_t handle) {
            MyGoPrint(handle);
        }

    Some C functions accept a void* argument that points to an arbitrary
    data value supplied by the caller. It is not safe to coerce a Handle (an
    integer) to a Go unsafe.Pointer, but instead we can pass the address of
    the cgo.Handle to the void* parameter, as in this variant of the previous
    example.

    Note that, as described in the cmd/cgo documentation, the C code must
    not keep a copy of the Go pointer that it receives, unless the memory is
    explicitly pinned using runtime.Pinner. This example is OK because the C
    function myprint does not keep a copy of the pointer.

        package main

        /*
        extern void MyGoPrint(void *context);
        static inline void myprint(void *context) {
            MyGoPrint(context);
        }
        */
        import "C"
        import (
        	"runtime/cgo"
        	"unsafe"
        )

        //export MyGoPrint
        func MyGoPrint(context unsafe.Pointer) {
        	h := *(*cgo.Handle)(context)
        	val := h.Value().(string)
        	println(val)
        	h.Delete()
        }

        func main() {
        	val := "hello Go"
        	h := cgo.NewHandle(val)
        	// In this example, unsafe.Pointer(&h) is valid because myprint
        	// does not keep a copy of the pointer. If the C code keeps the
        	// pointer after the call returns, use runtime.Pinner to pin it.
        	C.myprint(unsafe.Pointer(&h))
        	// Output: hello Go
        }

func NewHandle(v any) Handle
    NewHandle returns a handle for a given value.

    The handle is valid until the program calls Delete on it. The handle uses
    resources, and this package assumes that C code may hold on to the handle,
    so a program must explicitly call Delete when the handle is no longer
    needed.

    The intended use is to pass the returned handle to C code, which passes it
    back to Go, which calls Value.

func (h Handle) Delete()
    Delete invalidates a handle. This method should only be called once the
    program no longer needs to pass the handle to C and the C code no longer has
    a copy of the handle value.

    The method panics if the handle is invalid.

func (h Handle) Value() any
    Value returns the associated Go value for a valid handle.

    The method panics if the handle is invalid.

type Incomplete struct {
	// Has unexported fields.
}
    Incomplete is used specifically for the semantics of incomplete C types.

